// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intent.classifierimport com.roshan.persona.brain.intent.Intentimport kotlin.math.cosimport kotlin.math.sqrtimport kotlin.reflect.KClassimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Stage 3: Embedding Similarity Matcher. * * Uses a sentence embedding model (TFLite MiniLM-L6, 22MB) to compute cosine * similarity between input and pre-computed canonical phrases per intent. * * Top-1 with cosine similarity > 0.82 → match. Cold start kept warm in * memory (interpreter reused). * * The actual TFLite integration lives in :feature:vision (Module 6). Brain * uses [EmbedderInterface] to keep this module testable without TFLite. * * @see <a href="docs/spec/module2-spec-review.pdf">§4.1 Stage 3</a> */@Singletonclass EmbeddingIntentMatcher @Inject constructor(    private val embedder: EmbedderInterface,) {    /** Pre-computed embeddings per intent — lazily computed on first use. */    @Volatile    private var cachedEmbeddings: Map<KClass<out Intent>, FloatArray>? = null    /** Get cached embeddings (compute on first call). */    private suspend fun getEmbeddings(): Map<KClass<out Intent>, FloatArray> {        cachedEmbeddings?.let { return it }        val computed = computeIntentEmbeddings()        cachedEmbeddings = computed        return computed    }    /**     * Try to match [input] against intent embeddings.     *     * @return [EmbeddingMatch] if best similarity ≥ threshold, null otherwise.     */    suspend fun match(input: String): EmbeddingMatch? {        val inputEmbedding = embedder.embed(input).getOrElse { return null }        val intentEmbeddings = getEmbeddings()        var bestMatch: EmbeddingMatch? = null        var bestSimilarity = 0f        for ((intentType, intentEmbedding) in intentEmbeddings) {            val similarity = cosineSimilarity(inputEmbedding, intentEmbedding)            if (similarity > SIMILARITY_THRESHOLD && similarity > bestSimilarity) {                bestSimilarity = similarity                bestMatch = EmbeddingMatch(                    intent = canonicalIntent(intentType),                    rawSimilarity = similarity,                    intentType = intentType,                )            }        }        return bestMatch    }    /** Compute pre-computed embeddings for each intent (called once). */    private suspend fun computeIntentEmbeddings(): Map<KClass<out Intent>, FloatArray> {        val result = mutableMapOf<KClass<out Intent>, FloatArray>()        for ((intentType, phrases) in CANONICAL_PHRASES) {            val embeddings = mutableListOf<FloatArray>()            for (phrase in phrases) {                val emb = embedder.embed(phrase).getOrNull() ?: continue                embeddings.add(emb)            }            if (embeddings.isNotEmpty()) {                result[intentType] = averageEmbeddings(embeddings)            }        }        return result    }    /** Average multiple embeddings into one (element-wise mean). */    private fun averageEmbeddings(embeddings: List<FloatArray>): FloatArray {        val dim = embeddings[0].size        val avg = FloatArray(dim)        for (emb in embeddings) {            for (i in 0 until dim.coerceAtMost(emb.size)) {                avg[i] += emb[i]            }        }        for (i in avg.indices) {            avg[i] /= embeddings.size        }        return avg    }    /** Cosine similarity between two vectors. */    private fun cosineSimilarity(a: FloatArray, b: FloatArray): Float {        val dim = minOf(a.size, b.size)        var dot = 0f        var normA = 0f        var normB = 0f        for (i in 0 until dim) {            dot += a[i] * b[i]            normA += a[i] * a[i]            normB += b[i] * b[i]        }        if (normA == 0f || normB == 0f) return 0f        return dot / (sqrt(normA) * sqrt(normB))    }    /** Create canonical (slot-empty) intent instance for the matched type. */    private fun canonicalIntent(intentType: KClass<out Intent>): Intent {        return when (intentType) {            Intent.TorchOn::class -> Intent.TorchOn            Intent.TorchOff::class -> Intent.TorchOff            Intent.Call::class -> Intent.Call(contact = null)            Intent.SendSms::class -> Intent.SendSms(contact = null, message = null)            Intent.SendEmail::class -> Intent.SendEmail(to = null, subject = null, body = null)            Intent.OpenApp::class -> Intent.OpenApp(packageName = null, appName = null)            Intent.SearchWeb::class -> Intent.SearchWeb(query = null)            Intent.Question::class -> Intent.Question(topic = null, raw = "")            Intent.Explain::class -> Intent.Explain(topic = null, raw = "")            Intent.Summarize::class -> Intent.Summarize(target = null, raw = "")            Intent.Translate::class -> Intent.Translate(text = null, targetLanguage = null)            Intent.SetAlarm::class -> Intent.SetAlarm(time = null, label = null)            Intent.SetTimer::class -> Intent.SetTimer(duration = null, label = null)            Intent.SetReminder::class -> Intent.SetReminder(text = null, time = null)            Intent.CreateNote::class -> Intent.CreateNote(text = null)            Intent.CreateCalendarEvent::class -> Intent.CreateCalendarEvent(title = null, time = null, location = null)            Intent.CreateAutomation::class -> Intent.CreateAutomation(trigger = null, action = null)            else -> Intent.Unknown(raw = "")        }    }    /** Result of embedding match. */    data class EmbeddingMatch(        val intent: Intent,        val rawSimilarity: Float,        val intentType: KClass<out Intent>,    )    companion object {        /**         * Above this cosine similarity → match.         *         * Note: 0.3 is appropriate for TF-IDF embeddings (bag-of-words).         * When Module 6 ships TFLite MiniLM (transformer embeddings),         * this should be raised to 0.82.         */        const val SIMILARITY_THRESHOLD = 0.3f        /** Canonical phrases per intent — used to compute intent embeddings. */        val CANONICAL_PHRASES: Map<KClass<out Intent>, List<String>> = mapOf(            Intent.TorchOn::class to listOf(                "turn on the torch", "enable flashlight", "switch on the light",                "i need some light", "torch on", "flashlight on",            ),            Intent.TorchOff::class to listOf(                "turn off the torch", "disable flashlight", "switch off the light",                "torch off", "flashlight off", "kill the light",            ),            Intent.Call::class to listOf(                "call mom", "make a call", "phone dad", "ring my wife",                "dial this number", "call my friend",            ),            Intent.SendSms::class to listOf(                "send sms", "text message", "send a text", "message him",                "sms to mom", "text her",            ),            Intent.SendEmail::class to listOf(                "send email", "compose mail", "email rohan", "write an email",                "mail the team",            ),            Intent.OpenApp::class to listOf(                "open youtube", "launch spotify", "start calculator",                "open whatsapp", "launch the browser",            ),            Intent.SearchWeb::class to listOf(                "search for cats", "google einstein", "look up weather",                "find restaurants nearby", "search the web",            ),            Intent.Question::class to listOf(                "what is the capital of france", "how tall is mount everest",                "when was einstein born", "who invented the telephone",                "what's the population of india",            ),            Intent.Explain::class to listOf(                "explain quantum computing", "how does photosynthesis work",                "what is machine learning", "explain relativity",                "how do airplanes fly",            ),            Intent.Summarize::class to listOf(                "summarize this article", "give me the tldr",                "summarize the meeting notes", "what's the gist",                "make a summary of this",            ),            Intent.Translate::class to listOf(                "translate this to spanish", "how do you say hello in french",                "translate to hindi", "what's goodbye in japanese",                "convert this to german",            ),            Intent.SetAlarm::class to listOf(                "set alarm for 7 am", "wake me up at 6", "set an alarm",                "alarm for tomorrow morning", "set a wake up alarm",            ),            Intent.SetTimer::class to listOf(                "set timer for 10 minutes", "start a 5 minute timer",                "set a timer", "timer for 30 seconds",                "countdown for 2 minutes",            ),            Intent.SetReminder::class to listOf(                "remind me to call mom", "set a reminder",                "remind me about the meeting", "don't let me forget",                "remind me later",            ),            Intent.CreateNote::class to listOf(                "take a note", "write this down", "note that", "jot this down",                "save this as a note",            ),            Intent.CreateCalendarEvent::class to listOf(                "schedule a meeting", "add to calendar", "create an event",                "block time tomorrow", "set up a calendar event",            ),            Intent.CreateAutomation::class to listOf(                "when i get home dim the lights", "automate this",                "create a rule", "trigger when battery low",                "set up an automation",            ),        )    }}/** * Embedder interface — abstracts TFLite MiniLM. * * Real implementation in :feature:vision (Module 6). Brain uses this to * stay testable without TFLite. */interface EmbedderInterface {    /** Embed text into a 384-dim float vector. */    suspend fun embed(text: String): Result<FloatArray>}
